<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class QuotationService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly ?SubscriptionService $subscriptions=null,private readonly ?SiteAccessService $access=null) {}
    private function extraSite(array $q,bool $deciding=false):void {$extra=$this->db->fetch('SELECT * FROM extra_service_requests WHERE company_id=:company AND quotation_id=:id',['company'=>$this->company(),'id'=>$q['quotation_id']]);if(!$extra)return;$site=$this->access?$this->access->requireSite($extra['site_id']):$this->site($extra['site_id']);if((string)$site['client_id']!==(string)$q['client_id'])throw HttpException::notFound();if($deciding&&($extra['state']!=='QUOTED'||$extra['starts_at']<=gmdate('Y-m-d H:i:s')))throw HttpException::conflict('Extra-service request is no longer awaiting a current quote decision.');}
    private function mapped(mixed $client): void {if(!$this->db->fetch('SELECT client_id FROM client_portal_access WHERE company_id=:company AND client_id=:client AND user_id=:actor',['company'=>$this->company(),'client'=>$this->number($client),'actor'=>$this->actor()]))throw HttpException::notFound('Client quotation not found.');}
    private function values(array $input): array {
        $this->fields($input,['client_id','proposed_site_name','title','currency','lines','tax_basis_points','terms','valid_until','expected_revision']);$client=$this->row('clients','client_id',$input['client_id']??null);$currency=$input['currency']??null;if(!in_array($currency,['ZAR','USD','EUR','GBP','NAD','BWP'],true))throw HttpException::unprocessable('Choose a supported currency with two decimal minor units.');$lines=$input['lines']??null;if(!is_array($lines)||!array_is_list($lines)||count($lines)<1||count($lines)>30)throw HttpException::unprocessable('Add between one and 30 monthly-service quotation lines.');$out=[];$subtotal=0;foreach($lines as$line){if(!is_array($line))throw HttpException::unprocessable('Invalid quotation line.');$this->fields($line,['description','quantity','unit_minor']);$quantity=$this->number($line['quantity']??null,1,100000);$unit=$this->number($line['unit_minor']??null,0,100000000);$amount=$quantity*$unit;$subtotal+=$amount;if($subtotal>1000000000000)throw HttpException::unprocessable('Quotation total exceeds the supported amount.');$out[]=['description'=>$this->text($line['description']??null,500),'quantity'=>$quantity,'unit_minor'=>$unit,'amount_minor'=>$amount];}$basis=$this->number($input['tax_basis_points']??0,0,10000);$tax=intdiv($subtotal*$basis+5000,10000);$until=$this->day($input['valid_until']??null);if($until<gmdate('Y-m-d')||strtotime($until.' UTC')>time()+366*86400)throw HttpException::unprocessable('Choose a validity date from today through the next year.');return ['client'=>$client['client_id'],'site_name'=>$this->text($input['proposed_site_name']??null,150),'title'=>$this->text($input['title']??null,150),'currency'=>$currency,'lines'=>json_encode($out,JSON_THROW_ON_ERROR),'subtotal'=>$subtotal,'basis'=>$basis,'tax'=>$tax,'total'=>$subtotal+$tax,'terms'=>$this->text($input['terms']??null,10000),'until'=>$until];
    }
    public function create(array $input): array {return $this->atomic(function()use($input){$v=$this->values($input);$this->db->execute('INSERT INTO service_quotations(company_id,client_id,proposed_site_name,title,currency,lines_json,subtotal_minor,tax_basis_points,tax_minor,total_minor,terms,valid_until,created_by_user_id,created_at) VALUES(:company,:client,:site_name,:title,:currency,:lines,:subtotal,:basis,:tax,:total,:terms,:until,:actor,:now)',$v+['company'=>$this->company(),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('service_quotation');});}
    public function list(bool $client=false): array {
        $rows=$this->db->fetchAll('SELECT q.quotation_id,q.client_id,q.proposed_site_name,q.title,q.currency,q.subtotal_minor,q.tax_minor,q.total_minor,q.valid_until,q.state,q.revision,q.shared_hash,q.accepted_at FROM service_quotations q WHERE q.company_id=:company'.($client?" AND q.state<>'DRAFT' AND EXISTS(SELECT 1 FROM client_portal_access a WHERE a.company_id=q.company_id AND a.client_id=q.client_id AND a.user_id=:actor)":'').' ORDER BY q.quotation_id DESC LIMIT 500',$client?['company'=>$this->company(),'actor'=>$this->actor()]:['company'=>$this->company()]);foreach($rows as&$r)$r['expired']=$r['state']==='SHARED'&&$r['valid_until']<gmdate('Y-m-d');unset($r);if($client)$rows=array_values(array_filter($rows,function($r){try{$this->extraSite($r);return true;}catch(HttpException $e){if($e->statusCode()!==404)throw $e;return false;}}));return $rows;
    }
    public function detail(string $id,bool $client=false): array {$q=$this->row('service_quotations','quotation_id',$id);if($client){$this->extraSite($q);$this->mapped($q['client_id']);if($q['state']==='DRAFT')throw HttpException::notFound();unset($q['created_by_user_id']);}$q['lines']=json_decode($q['lines_json'],true,512,JSON_THROW_ON_ERROR);unset($q['lines_json']);return $q;}
    private function hash(array $q): string {return hash('sha256',json_encode(array_map(static fn($k)=>(string)$q[$k],['quotation_id','client_id','proposed_site_name','title','currency','lines_json','subtotal_minor','tax_basis_points','tax_minor','total_minor','terms','valid_until']),JSON_THROW_ON_ERROR));}
    public function update(string $id,array $input): array {return $this->atomic(function()use($id,$input){$q=$this->row('service_quotations','quotation_id',$id);if($q['state']!=='DRAFT'||$this->number($input['expected_revision']??null)!==(int)$q['revision'])throw HttpException::conflict('Only the current draft can be edited.');$v=$this->values($input);$this->db->execute('UPDATE service_quotations SET client_id=:client,proposed_site_name=:site_name,title=:title,currency=:currency,lines_json=:lines,subtotal_minor=:subtotal,tax_basis_points=:basis,tax_minor=:tax,total_minor=:total,terms=:terms,valid_until=:until,revision=revision+1 WHERE company_id=:company AND quotation_id=:id',$v+['company'=>$this->company(),'id'=>$id]);$this->audit->record('service_quotation','draft_updated',$id);return ['revision'=>(int)$q['revision']+1];});}
    public function share(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$q=$this->row('service_quotations','quotation_id',$id);if($q['state']!=='DRAFT'||$this->number($input['expected_revision']??null)!==(int)$q['revision']||$q['valid_until']<gmdate('Y-m-d'))throw HttpException::conflict('Only a current, unexpired draft can be shared.');$hash=$this->hash($q);$this->db->execute("UPDATE service_quotations SET state='SHARED',shared_hash=:hash,shared_at=:now,revision=revision+1 WHERE company_id=:company AND quotation_id=:id",['hash'=>$hash,'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('service_quotation','shared_to_client_portal',$id);return ['shared'=>true,'shared_hash'=>$hash,'revision'=>(int)$q['revision']+1,'note'=>'Available to mapped client accounts in their portal; this action does not send email.'];});}
    public function decide(string $id,string $action,array $input): array {return $this->atomic(function()use($id,$action,$input){$this->fields($input,['expected_hash','notes']);$q=$this->row('service_quotations','quotation_id',$id);$this->mapped($q['client_id']);$this->extraSite($q,true);if($q['state']!=='SHARED'||$q['valid_until']<gmdate('Y-m-d')||!is_string($input['expected_hash']??null)||!hash_equals((string)$q['shared_hash'],$input['expected_hash'])||!hash_equals($this->hash($q),(string)$q['shared_hash']))throw HttpException::conflict('Quotation expired, changed or was already decided. Read the current offer.');if(!in_array($action,['accept','decline'],true))throw HttpException::notFound();$state=$action==='accept'?'ACCEPTED':'DECLINED';$this->db->execute('UPDATE service_quotations SET state=:state,revision=revision+1,accepted_at=:now,accepted_by_user_id=:actor,decision_notes=:notes WHERE company_id=:company AND quotation_id=:id',['state'=>$state,'now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'notes'=>$this->text($input['notes']??null,1000),'company'=>$this->company(),'id'=>$id]);$extra=$this->db->fetch("SELECT request_id FROM extra_service_requests WHERE company_id=:company AND quotation_id=:id AND state='QUOTED'",['company'=>$this->company(),'id'=>$id]);if($extra){$this->db->execute('UPDATE extra_service_requests SET state=:state,revision=revision+1 WHERE company_id=:company AND request_id=:id',['state'=>$state,'company'=>$this->company(),'id'=>$extra['request_id']]);$this->db->execute('INSERT INTO service_delivery_history(company_id,entity_kind,entity_id,action_name,notes,actor_user_id,occurred_at) VALUES(:company,:kind,:id,:action,:notes,:actor,:now)',['company'=>$this->company(),'kind'=>'extra_service','id'=>$extra['request_id'],'action'=>$state,'notes'=>$input['notes'],'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);}$this->audit->record('service_quotation',$action,$id);return ['state'=>$state,'note'=>'Records an authenticated portal decision, not an independently certified electronic signature.'];});}
    public function convert(string $id,array $input): array {return $this->atomic(function()use($id,$input){
        $this->fields($input,['branch_id','contract_number','start_date','end_date','required_guards','address']);if($this->db->fetch('SELECT request_id FROM extra_service_requests WHERE company_id=:company AND quotation_id=:id',['company'=>$this->company(),'id'=>$id]))throw HttpException::conflict('One-off extra-service quotations fulfil existing sites and cannot be converted into monthly contracts.');$q=$this->row('service_quotations','quotation_id',$id);$canonical=$input;ksort($canonical);$hash=hash('sha256',json_encode($canonical,JSON_THROW_ON_ERROR));$old=$this->db->fetch('SELECT onboarding_id,contract_id,site_id,conversion_hash FROM site_onboardings WHERE company_id=:company AND quotation_id=:id',['company'=>$this->company(),'id'=>$id]);if($old){if(!hash_equals($old['conversion_hash'],$hash))throw HttpException::conflict('Quotation was already converted with different setup details.');unset($old['conversion_hash']);return array_map('strval',$old);}
        if($q['state']!=='ACCEPTED'||!hash_equals($this->hash($q),(string)$q['shared_hash']))throw HttpException::conflict('A current accepted quotation is required.');$this->subscriptions?->assertCanCreate('sites');$branch=$this->row('branches','branch_id',$input['branch_id']??null);if((string)$branch['client_id']!==(string)$q['client_id']||($branch['status']??null)!=='ACTIVE')throw HttpException::unprocessable('Choose an active branch belonging to the quoted client.');$start=$this->day($input['start_date']??null);$end=empty($input['end_date'])?null:$this->day($input['end_date']);if($end!==null&&$end<$start)throw HttpException::unprocessable('Contract end must follow its start.');$number=$this->text($input['contract_number']??null,100);$guards=$this->number($input['required_guards']??null,1,10000);
        if($this->db->fetch('SELECT contract_id FROM contracts WHERE company_id=:company AND contract_number=:number',['company'=>$this->company(),'number'=>$number])||$this->db->fetch('SELECT site_id FROM sites WHERE company_id=:company AND branch_id=:branch AND site_name=:name',['company'=>$this->company(),'branch'=>$branch['branch_id'],'name'=>$q['proposed_site_name']]))throw HttpException::conflict('Contract number or proposed site name is already in use.');$meta=json_encode(['quotation_id'=>$q['quotation_id'],'accepted_hash'=>$q['shared_hash'],'currency'=>$q['currency'],'monthly_subtotal_minor'=>$q['subtotal_minor'],'tax_minor'=>$q['tax_minor']],JSON_THROW_ON_ERROR);
        $this->db->execute("INSERT INTO contracts(contract_uuid,company_id,client_id,contract_number,contract_name,start_date,end_date,monthly_value,required_guard_count,shift_requirements_json,status,created_by_user_id) VALUES(:uuid,:company,:client,:number,:name,:start,:end,:monthly,:guards,:meta,'DRAFT',:actor)",['uuid'=>uuid4(),'company'=>$this->company(),'client'=>$q['client_id'],'number'=>$number,'name'=>$q['title'],'start'=>$start,'end'=>$end,'monthly'=>number_format((int)$q['subtotal_minor']/100,2,'.',''),'guards'=>$guards,'meta'=>$meta,'actor'=>$this->actor()]);$contract=(string)$this->db->connection()->lastInsertId();
        $this->db->execute("INSERT INTO sites(company_id,client_id,branch_id,contract_id,site_name,address,status) VALUES(:company,:client,:branch,:contract,:name,:address,'ONBOARDING')",['company'=>$this->company(),'client'=>$q['client_id'],'branch'=>$branch['branch_id'],'contract'=>$contract,'name'=>$q['proposed_site_name'],'address'=>$this->text($input['address']??null,2000)]);$site=(string)$this->db->connection()->lastInsertId();$this->db->execute('INSERT INTO site_onboardings(company_id,quotation_id,contract_id,site_id,conversion_hash,created_by_user_id,created_at) VALUES(:company,:quote,:contract,:site,:hash,:actor,:now)',['company'=>$this->company(),'quote'=>$id,'contract'=>$contract,'site'=>$site,'hash'=>$hash,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$onboarding=(string)$this->db->connection()->lastInsertId();
        foreach(['Review contract and client acceptance','Publish site instructions and emergency contacts','Confirm guard deployment, availability and training','Commission and test QR/NFC checkpoints','Issue equipment and test radios','Map client portal access and report schedules','Rehearse emergency response and supervisor recovery']as$task)$this->db->execute('INSERT INTO mobilisation_tasks(company_id,onboarding_id,task_name) VALUES(:company,:onboarding,:task)',['company'=>$this->company(),'onboarding'=>$onboarding,'task'=>$task]);$this->db->execute("UPDATE service_quotations SET state='CONVERTED',revision=revision+1 WHERE company_id=:company AND quotation_id=:id",['company'=>$this->company(),'id'=>$id]);$this->audit->record('service_quotation','converted_to_onboarding',$id,[],[],['contract_id'=>$contract,'site_id'=>$site,'onboarding_id'=>$onboarding]);return ['onboarding_id'=>$onboarding,'contract_id'=>$contract,'site_id'=>$site];
    });}
    public function onboardings(): array {$rows=$this->db->fetchAll('SELECT * FROM site_onboardings WHERE company_id=:company ORDER BY onboarding_id DESC LIMIT 200',['company'=>$this->company()]);foreach($rows as&$r){unset($r['conversion_hash']);$r['tasks']=$this->db->fetchAll('SELECT * FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id ORDER BY task_id',['company'=>$this->company(),'id'=>$r['onboarding_id']]);}unset($r);return $rows;}
    public function completeTask(string $id,array $input): array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','evidence_reference']);$task=$this->row('mobilisation_tasks','task_id',$id);$onboarding=$this->row('site_onboardings','onboarding_id',$task['onboarding_id']);if($onboarding['state']!=='PREPARING'||$task['completed_at']!==null||$this->number($input['expected_revision']??null)!==(int)$task['revision'])throw HttpException::conflict('Task or onboarding changed. Refresh first.');$this->db->execute('UPDATE mobilisation_tasks SET completed_at=:now,completed_by_user_id=:actor,evidence_reference=:reference,revision=revision+1 WHERE company_id=:company AND task_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'reference'=>$this->text($input['evidence_reference']??null,1000),'company'=>$this->company(),'id'=>$id]);$this->audit->record('mobilisation_task','completed',$id);return ['completed'=>true];});}
    public function activate(string $id): array {return $this->atomic(function()use($id){$o=$this->row('site_onboardings','onboarding_id',$id);$contract=$this->row('contracts','contract_id',$o['contract_id']);$site=$this->site($o['site_id']);$packet=$this->db->fetch('SELECT * FROM client_mobilisation_reviews WHERE company_id=:company AND onboarding_id=:id',['company'=>$this->company(),'id'=>$id]);if($packet){$tasks=$this->db->fetchAll('SELECT task_id,task_name,revision,completed_at,evidence_reference FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id ORDER BY task_id',['company'=>$this->company(),'id'=>$id]);if($packet['state']!=='ACCEPTED'||(string)$packet['client_id']!==(string)$site['client_id']||!hash_equals($packet['packet_hash'],ClientDeliveryService::readinessHash($contract,$site,$tasks,$packet['contacts_json'],$packet['survey_reference'])))throw HttpException::conflict('Client mobilisation approval is absent or stale.');}if($o['state']!=='PREPARING'||$contract['status']!=='DRAFT'||($site['status']??null)!=='ONBOARDING'||!empty($contract['deleted_at']))throw HttpException::conflict('Only a draft contract and preparing site can be activated.');if((int)$this->db->fetch('SELECT COUNT(*) AS n FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id',['company'=>$this->company(),'id'=>$id])['n']!==7)throw HttpException::conflict('The mobilisation checklist is incomplete.');if($this->db->fetch('SELECT task_id FROM mobilisation_tasks WHERE company_id=:company AND onboarding_id=:id AND completed_at IS NULL',['company'=>$this->company(),'id'=>$id]))throw HttpException::conflict('Complete every mobilisation check with evidence before activation.');$this->db->execute("UPDATE contracts SET status='ACTIVE',updated_by_user_id=:actor WHERE company_id=:company AND contract_id=:id",['actor'=>$this->actor(),'company'=>$this->company(),'id'=>$o['contract_id']]);$this->db->execute("UPDATE sites SET status='ACTIVE',updated_by_user_id=:actor WHERE company_id=:company AND site_id=:id",['actor'=>$this->actor(),'company'=>$this->company(),'id'=>$o['site_id']]);$this->db->execute("UPDATE site_onboardings SET state='ACTIVE',activated_by_user_id=:actor,activated_at=:now WHERE company_id=:company AND onboarding_id=:id",['actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$id]);$this->audit->record('site_onboarding','activated',$id);return ['activated'=>true];});}
}
